  "diagnosis": "F22",
  "candidates": ["F22", "F06.2", "F20.0"],
  "reason": "The patient has a persistent, systematized persecutory delusion lasting for months, centered on being deliberately sabotaged and excluded from decisions regarding her sister. There are no hallucinations, no Schneiderian/passivity symptoms, no clear mood episode, and functioning appears relatively preserved outside the delusional system. This best fits persistent delusional disorder, persecutory type.",
  "diagnostic_checklist": {
    "symptom_groups": [
      {
        "group": "persecutory_delusions",
        "confirmed_symptoms": [
          belief that family and clinic staff are deliberately keeping information from her",
          belief that medical appointments and bills are being manipulated on purpose",
          belief that people are coordinating to push her out of decision-making for her sister",
          conviction that others are lying or hiding information despite evidence to the contrary"
        ],
        "count": 4
      }
    ],
    "duration_verified": "Symptoms have been present for months.",
    "functional_impairment": true,
    "traumatic_stressor": false,
    "psychosocial_stressor": true,
    "additional_requirements": [
      "No hallucinations reported",
      "No thought insertion, withdrawal, or broadcasting reported",
      "No depressive episode of at least two weeks reported",
      "No prior similar delusional episodes reported",
      "Relatively preserved occupational functioning outside the delusional preoccupation"
    ]
  }
}

